// Demo: Signature PCIe Enumeration — PCIe BAR sizing
var bars=[['BAR0',4],['BAR1',256],['BAR2',1]];
console.log('technique: Signature PCIe Enumeration');
var total=0;bars.forEach(function(b){console.log(b[0]+': '+b[1]+' KB');total+=b[1];});
console.log('total MMIO window: '+total+' KB');

// Demo: Signature I2C Transactions — I2C transaction timing
var bits=8+1,clk=100000;
var us=(bits*2/clk)*1e6;
console.log('technique: Signature I2C Transactions');console.log('100 kHz I2C byte + ACK: '+us.toFixed(0)+' us');
console.log('400 kHz fast mode: '+(us/4).toFixed(0)+' us — clock speed sets throughput');

